def anti_shuffle(s):
    words = s.split(' ')
    ordered_words = []

    for word in words:
        if word:  # Only process non-empty words
            ordered_words.append(''.join(sorted(word)))
        else:
            ordered_words.append('')  # Preserve empty spaces

    result = []
    word_index = 0

    for char in s:
        if char == ' ':
            result.append(char)
        else:
            result.append(ordered_words[word_index])
            word_index += 1

    return ''.join(result)

